pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    function testFuzz_property(uint160 fromAddr, uint256 amount, bool succeed) public {
        address from = address(uint160(bound(fromAddr, 1, type(uint160).max)));

        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);
        vals[0] = amount;

        CalleeHelper helper = new CalleeHelper(succeed);
        tos[0] = address(0xBEEF);

        address caddress = address(helper);

        bool ok;
        try c.transfer(from, caddress, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        if (succeed) {
            assertTrue(ok);
        } else {
            assertTrue(true);
        }
    }
}

contract CalleeHelper {
    bool public willSucceed;
    constructor(bool _succeed) { willSucceed = _succeed; }

    function transferFrom(address, address, uint256) external returns (bool) {
        if (willSucceed) {
            return true;
        } else {
            revert("fail");
        }
    }

    fallback() external payable {
        if (willSucceed) {
            assembly {
                mstore(0x00, 1)
                return(0x00, 0x20)
            }
        } else {
            revert("fail");
        }
    }
}
